using System;using System.IO;using System.Linq;using System.Diagnostics;using UnityEditor;using UnityEngine;
namespace RebirthEntityStudio {
 public sealed class RebirthHeadSkinDetailJob:IDisposable {
  [Serializable]sealed class Mapping {public float[] positions,normals,tangents,uv;public int[] triangles;public string normal,coverage;public float poreStrength;}
  [Serializable]sealed class Report {public string sourceMappingSha256,sourceNormalSha256,sourceCoverageSha256,normalSha256,heightSha256;public float tileSizeMetres;}
  bool started;Process process;readonly DateTime start=DateTime.UtcNow;string folder,settingsPath,settingsHash,normal,normalHash,coverage,coverageHash,mappingHash,errors="";BodyRecipe original;float strength,smoothness;
  public bool Finished{get;private set;}public string Error{get;private set;}public string Status{get;private set;}="Preparing head skin detail";public float Progress{get;private set;}public BodyRecipe Candidate{get;private set;}
  public int? WorkerProcessId{get{try{return process==null?null:(int?)process.Id;}catch(InvalidOperationException){return null;}}}
  static string Hash(string path){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
  static string Quote(string path){if(string.IsNullOrEmpty(path)||path.IndexOfAny(new[]{'"','\r','\n'})>=0)throw new ArgumentException("Invalid detail path");return "\""+path+"\"";}
  static string Find(string name,string suffix)=>AssetDatabase.FindAssets(name).Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith(suffix,StringComparison.Ordinal));
  public static void ValidateSource(TextAsset settings){
   if(settings==null)throw new ArgumentException("Choose generated head settings first");var face=JsonUtility.FromJson<FaceRecipe>(settings.text);face.Validate(RebirthFaceGeneratorWindow.ReadTemplate());var material=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(face.generatedMaterialGuid));if(material==null||material.mainTexture==null||!material.HasProperty("_BumpMap")||material.GetTexture("_BumpMap")==null)throw new InvalidDataException("Head detail needs a generated skin normal map");if(material.mainTextureScale!=Vector2.one||material.mainTextureOffset!=Vector2.zero)throw new InvalidDataException("Head detail needs an untransformed generated skin atlas");string coverage=Path.Combine(Path.GetDirectoryName(AssetDatabase.GetAssetPath(material.mainTexture)),"SourceCoverage.png");if(!File.Exists(coverage))throw new FileNotFoundException("Head snapshot lacks SourceCoverage.png; choose original generated head settings or a current export with coverage");
  }
  public RebirthHeadSkinDetailJob(BodyTemplate template,BodyRecipe recipe,TextAsset settings){try{
   ValidateSource(settings);original=RebirthBodyGenerationJob.Clone(recipe);original.Validate(template);var face=JsonUtility.FromJson<FaceRecipe>(settings.text);var layout=RebirthFaceGeneratorWindow.ReadTemplate();face.Validate(layout);
   var material=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(face.generatedMaterialGuid));if(material==null||material.mainTexture==null||!material.HasProperty("_BumpMap")||material.GetTexture("_BumpMap")==null)throw new InvalidDataException("Head detail needs a generated skin normal map");
   normal=Path.GetFullPath(AssetDatabase.GetAssetPath(material.GetTexture("_BumpMap")));coverage=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(AssetDatabase.GetAssetPath(material.mainTexture)),"SourceCoverage.png"));settingsPath=Path.GetFullPath(AssetDatabase.GetAssetPath(settings));
   if(!File.Exists(coverage))throw new FileNotFoundException("This head snapshot lacks source coverage. Choose the original generated head settings or a head exported with observation coverage.");
   normalHash=Hash(normal);coverageHash=Hash(coverage);settingsHash=Hash(settingsPath);strength=Mathf.Clamp01(face.poreDetail);smoothness=face.skinSmoothness;
   folder=Path.GetFullPath("Library/RebirthHeadSkinDetail/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);var mesh=RebirthFaceGeneratorModel.Build(layout,face);string mapping=Path.Combine(folder,"Mapping.json");try{File.WriteAllText(mapping,JsonUtility.ToJson(new Mapping{positions=mesh.vertices.SelectMany(v=>new[]{v.x,v.y,v.z}).ToArray(),normals=mesh.normals.SelectMany(v=>new[]{v.x,v.y,v.z}).ToArray(),tangents=mesh.tangents.SelectMany(v=>new[]{v.x,v.y,v.z,v.w}).ToArray(),uv=mesh.uv.SelectMany(v=>new[]{v.x,v.y}).ToArray(),triangles=mesh.GetTriangles(0),normal=normal,coverage=coverage,poreStrength=face.poreDetail}));}finally{UnityEngine.Object.DestroyImmediate(mesh);}mappingHash=Hash(mapping);
   string backend=Find("extract_head_skin_detail","/BodyGeneratorData/Backend/extract_head_skin_detail.py");var config=RebirthFaceImageJob.ReadConfiguration();if(backend==null||!File.Exists(config.python))throw new FileNotFoundException("Install the head skin detail worker and configured Python runtime");
   var info=new ProcessStartInfo(config.python,Quote(Path.GetFullPath(backend))+" --source "+Quote(mapping)+" --output "+Quote(folder)+" --progress "+Quote(Path.Combine(folder,"progress.json"))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true};info.EnvironmentVariables["PYTHONDONTWRITEBYTECODE"]="1";process=new Process{StartInfo=info};process.OutputDataReceived+=(s,e)=>{};process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)lock(this){errors+=e.Data+"\n";if(errors.Length>12000)errors=errors.Substring(errors.Length-12000);}};process.Start();started=true;process.BeginOutputReadLine();process.BeginErrorReadLine();
  }catch{Dispose();throw;}}
  public void Poll(){if(Finished)return;try{
   string progress=Path.Combine(folder,"progress.json");try{if(File.Exists(progress)){FaceImageProgress state;using(var stream=new FileStream(progress,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream))state=JsonUtility.FromJson<FaceImageProgress>(reader.ReadToEnd());if(state!=null){Progress=Mathf.Max(Progress,Mathf.Clamp01(state.progress));Status=state.message;}}}catch(IOException){}
   if(!process.HasExited){if((DateTime.UtcNow-start).TotalSeconds>120)throw new TimeoutException("Head skin detail exceeded two minutes");return;}process.WaitForExit();if(process.ExitCode!=0){File.WriteAllText(Path.Combine(folder,"WorkerError.log"),errors);throw new InvalidOperationException("Head detail could not be sampled; current body retained. Details: "+Path.Combine(folder,"WorkerError.log"));}
   var report=JsonUtility.FromJson<Report>(File.ReadAllText(Path.Combine(folder,"Source.json")));if(report==null||report.sourceMappingSha256!=mappingHash||Hash(Path.Combine(folder,"Mapping.json"))!=mappingHash||report.sourceNormalSha256!=normalHash||report.sourceCoverageSha256!=coverageHash||Hash(normal)!=normalHash||Hash(coverage)!=coverageHash||Hash(settingsPath)!=settingsHash||report.normalSha256!=Hash(Path.Combine(folder,"HeadSkinMicroNormal.png"))||report.heightSha256!=Hash(Path.Combine(folder,"HeadSkinMicroHeight.png")))throw new InvalidDataException("Head detail inputs or outputs changed during generation");
   string target="Assets/BodyGeneratorGenerated/HeadDetail_"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(target);foreach(string file in new[]{"HeadSkinMicroNormal.png","HeadSkinMicroHeight.png","Source.json"}){File.Copy(Path.Combine(folder,file),target+"/"+file);AssetDatabase.ImportAsset(target+"/"+file);}
   foreach(string file in new[]{"HeadSkinMicroNormal.png","HeadSkinMicroHeight.png"}){var importer=(TextureImporter)AssetImporter.GetAtPath(target+"/"+file);importer.textureType=file.Contains("Normal")?TextureImporterType.NormalMap:TextureImporterType.Default;importer.sRGBTexture=false;importer.wrapMode=TextureWrapMode.Repeat;importer.mipmapEnabled=true;importer.maxTextureSize=512;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.filterMode=FilterMode.Trilinear;importer.SaveAndReimport();}
   var result=RebirthBodyGenerationJob.Clone(original);var surface=result.surface;surface.microNormalGuid=AssetDatabase.AssetPathToGUID(target+"/HeadSkinMicroNormal.png");surface.microHeightGuid=AssetDatabase.AssetPathToGUID(target+"/HeadSkinMicroHeight.png");surface.microSourceGuid=AssetDatabase.AssetPathToGUID(target+"/Source.json");if(string.IsNullOrEmpty(surface.microRegionsGuid)){string regions=Find("BodyMicroRegions","/BodyGeneratorData/SkinMicrodetail/BodyMicroRegions.png");if(regions==null)throw new FileNotFoundException("Install body microdetail region masks");RebirthBodyMicrodetail.PrepareDefault(regions,false);surface.microRegionsGuid=AssetDatabase.AssetPathToGUID(regions);}surface.microStrength=strength;surface.microTileSize=report.tileSizeMetres;surface.microRoughness=0;surface.microTorso=1;surface.microLimbs=.65f;surface.microExtremities=.35f;surface.smoothness=smoothness;surface.Validate();result.generationReportGuid="";
   File.WriteAllText(target+"/BodySettings.json",JsonUtility.ToJson(result,true));AssetDatabase.ImportAsset(target+"/BodySettings.json");Candidate=result;Progress=1;Status="Head-derived pore detail ready; body colour and shape retained";Finished=true;
  }catch(Exception e){Error=e.Message;Status=Error;Finished=true;Dispose();}}
  public void Dispose(){if(process==null)return;try{if(started&&!process.HasExited)process.Kill();}finally{process.Dispose();process=null;}}
 }
}
